          "mondaiName": "問題10：短文読解 (Đọc hiểu đoản văn)",
          "passage": "クルマ社会は、大人には便利な社会です。煩わしい思いをしなくても、夜や休日に自家用車で買い物に出れば、必要なものがほとんど手に入ります。店の営業時間は長く、定休日も基本的にありません。<br><br>しかし、クルマ社会は、子どもには不便きわまりない社会です。クルマを運転できない子どもたちは、クルマ社会の恩恵をほとんど享受することができません。むしろ、徒歩や自転車で移動する際に、自動車がたくさん走る道を通らねばなりませんから、常に肩身の狭い思いをします。クルマでしか動けない地域社会というのは、子どもの参加を拒んでいる社会にも見えます。<br><br>(加藤秀俊「外国人に「働いてもらう」不思議」『正論』2009年8月6日付け産経ニュース)",
