          "mondai": 11,
          "mondaiName": "問題11：中文読解 (Đọc hiểu trung văn)",
          "passage": "　ある日、私は貴重な体験をしました。東京都内で、ある会場からある会場へ移動する時に、電車の乗り継ぎが悪かったのでタクシーを拾うことにしました。私は昔からタクシーの運転手に声をかけるのが好きで、運転手の体験談（注1）や価値観を聞き出すことにいつもワクワクしているのです。この日も、今日は何が聞き出せるかなと楽しみに、止まっていたタクシーに乗りこみました。座った瞬間に、ふと違和感（注2）を感じました。<u>いつもと明らかに違う感覚</u>でした。私はさっそくその気持ちを素直にぶつけてみました。\n　「このタクシー、とても心地よく（注3）感じました」\n　さて、何と返答がくるのかワクワクです。ちょうど信号が赤になりました。後ろ姿は五十代に見えるその運転手が、私の方を振り向き、口を開きました。\n　「私も心地よいです」\n　私はその言葉に感動しました。その後、様々な話を聞き出すことができました。その運転手は、昔から運転が好きで、人を喜ばせることが大好きだそうで、ある会社を経営していたそうですが、タクシーの運転手が天職（注4）だと思い、思いきって転職をしたとのこと。その運転手の口から放たれる（注5）言葉に、とても共感を覚えたと同時に、あぁ、この人は表現者だなと確信したのです。\n（武田双雲『「書」を書く愉しみ』光文社）\n\n（注1）体験談：自分が経験したことの話\n（注2）違和感：普通の状態と少し違う感じ\n（注3）心地よく：気持ちよく\n（注4）天職：性質や才能にもっとも合った職業\n（注5）放たれる：発せられる",
          "sentence": "<u>いつもと明らかに違う感覚</u>とは、どんな感じか。",
