          "passage": "　現代人の脳を取り巻く環境の中で、10年前と今とでもっとも変わったことは何でしょうか？色々あるとは思いますが、最大の一つは、「小さな平面を見ている時間が長くなった」ということだと思います。\n　一日の生活を振り返ってみてください。一体どれだけ、テレビやパソコンの画面、携帯電話のモニターを見ている時間があるでしょうか？電車に乗っていても、人を観察したり外の景色を眺めたりするのではなく、携帯ゲーム機の画面を見つめていたり、車内に設置されたモニターを見ている場合がよくあると思います。\n　ITの普及が人間の脳にもたらして（注1）いる影響は、功罪両面（注2）があると私は考えていますが、この「小さな平面を見ている時間が長くなった」という一面に関しては、どう考えてもよくないことです。最近、思考の働きが鈍くなった、人から話しかけられたときにパッと反応できないことが多くなった……などと考えている人は、まず<u>この影響</u>を疑ってみる必要があるかもしれません。\n　あらかじめ（注3）断っておきますが、本章で申し上げたいのは、「だからITを使うのはやめよう」ということではありません。これからもっと積極的にITを活用していくべき時代だからこそ、この問題点にも気づき、対策を知ってくださいということです。\n（築山節『脳が冴える15の習慣・記憶・集中・思考力を高める』日本放送出版協会）\n\n（注1）もたらす：与える\n（注2）功罪両面：いいことと悪いことの両方\n（注3）あらかじめ：はじめに",
          "sentence": "<u>この影響</u>とあるが、何の影響か。",
