          "mondaiName": "問題11：中文読解 (Đọc hiểu trung văn)",
          "passage": "　わたしは、コミュニケーションの相手との「関係性」についても敏感さ（注1）を失わないようにしている。ただ「関係性」というのは、相手が目上なのか目下なのかというようなことではない。\n　日本の社会、特にサラリーマン社会では、目上、目下という上下関係が基本になる。だから①<u>名刺交換がないとどのレベルの敬語を使ったらいいか分からない</u>、という話を、外国に出張している人からよく聞く。目下の人か、目上の人か、目上だったら、どの程度上なのかを把握（注2）しないと日本語で会話するのが不可能なのだそうだ。英語で喋るときと日本語で喋るときで、別人になってしまうような感覚があるらしい。わたしは組織に所属して（注3）いないので、②<u>そういった「関係性」</u>に気を遣うことはない。相手が平社員であろうが部長であろうが関係ない。社長だから敬語がさらに丁寧になるということはない。\n　私が指摘する（注4）「関係性」というのは、肩書（注5）に代表される上下関係のようなものではなく、個別のひとりひとりに対する距離と公正さのことだ。その人とはどのくらい親しいのか、親しくないのか。全く未知の人なのか。あるいはその人はプライバシーを守らなくてはいけない有名人なのか、そうではないのか。さらに非常に多忙な人なのか、あるいは時間だけは充分ある人なのか。そういったことを含めて「関係性」と呼んでいる。\n（村上龍『eメールの達人になる』集英社）\n\n（注1）敏感さ：ものごとを早く感じられる性質\n（注2）把握する：意味や状況を理解すること\n（注3）所属する：グループの一員として加わる\n（注4）指摘する：問題などとして示すこと\n（注5）肩書：社会的な地位や身分など",
