<b>🎧 Nội dung bài nghe (Script tiếng Nhật):</b><br>
女の学生と男の学生が田中君のことを話しています。田中君はどうして先生に褒められたのですか。<br>
女：昨日田中君、先生に褒められたんだよ。<br>
